import React, { useState } from 'react';
import { Menu, X, LayoutDashboard } from 'lucide-react';

export default function Navbar({ activeScreen, setActiveScreen }) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const navLinks = [
    { name: 'Home', screen: 'home' },
    { name: 'Career Guidance', screen: 'guidance' },
    { name: 'Workshops', screen: 'workshops' },
    { name: 'Courses', screen: 'courses' },
    { name: 'Internships', screen: 'internships' },
    { name: 'B.Tech Projects', screen: 'btech-projects' },
    { name: 'M.Tech Projects', screen: 'mtech-projects' },
    { name: 'About', screen: 'about' },
    { name: 'Contact', screen: 'contact' },
  ];

  const handleNav = (screen) => {
    setActiveScreen(screen);
    setMobileMenuOpen(false);
  };

  return (
    <header className="sticky top-0 z-40 bg-slate-900/90 backdrop-blur-md border-b border-slate-800 text-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
        <div 
          onClick={() => handleNav('home')} 
          className="cursor-pointer flex items-center space-x-3"
        >
          <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-violet-600 to-emerald-500 flex items-center justify-center font-bold text-xl shadow-lg shadow-violet-500/20">
            VA
          </div>
          <div>
            <span className="text-xl font-bold tracking-tight bg-gradient-to-r from-white via-slate-200 to-emerald-400 bg-clip-text text-transparent">
              Vighnavi Academy
            </span>
            <p className="text-xs text-slate-400 -mt-1 tracking-wider uppercase">Wisdom. Knowledge. Success.</p>
          </div>
        </div>

        <nav className="hidden xl:flex items-center space-x-1">
          {navLinks.map((link) => (
            <button
              key={link.screen}
              onClick={() => handleNav(link.screen)}
              className={`px-3 py-2 rounded-lg text-sm font-medium transition-all duration-150 ${
                activeScreen === link.screen
                  ? 'bg-violet-600/30 text-emerald-400 border border-violet-500/30'
                  : 'text-slate-300 hover:text-white hover:bg-slate-800/60'
              }`}
            >
              {link.name}
            </button>
          ))}
        </nav>

        <div className="hidden xl:flex items-center space-x-3">
          <button
            onClick={() => handleNav('dashboard')}
            className="flex items-center space-x-2 bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 text-white px-4 py-2.5 rounded-xl font-medium text-sm shadow-md shadow-violet-700/20 transition-all transform active:scale-95"
          >
            <LayoutDashboard className="w-4 h-4 text-emerald-400" />
            <span>Dashboard</span>
          </button>
        </div>

        <div className="xl:hidden flex items-center space-x-2">
          <button
            onClick={() => handleNav('dashboard')}
            className="p-2 rounded-lg bg-slate-800 text-emerald-400"
          >
            <LayoutDashboard className="w-5 h-5" />
          </button>
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="p-2 rounded-lg bg-slate-800 text-slate-300 hover:text-white"
          >
            {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </div>
      </div>

      {mobileMenuOpen && (
        <div className="xl:hidden bg-slate-900 border-b border-slate-800 px-4 pt-2 pb-6 space-y-1">
          {navLinks.map((link) => (
            <button
              key={link.screen}
              onClick={() => handleNav(link.screen)}
              className={`w-full text-left px-4 py-3 rounded-lg text-sm font-medium ${
                activeScreen === link.screen
                  ? 'bg-violet-600/20 text-emerald-400 border border-violet-600/40'
                  : 'text-slate-300 hover:bg-slate-800'
              }`}
            >
              {link.name}
            </button>
          ))}
        </div>
      )}
    </header>
  );
}
